CREATE TABLE "customers" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "customers_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"code" text NOT NULL,
	"kind" text NOT NULL,
	"name" text NOT NULL,
	"search_text" text NOT NULL,
	"search_phonetic" text NOT NULL,
	"search_version" smallint NOT NULL,
	"reg_no" text,
	"tin" text,
	"tin_source" text,
	"consumer_no" text,
	"phone" text,
	"vat_payer" boolean DEFAULT false NOT NULL,
	"city_payer" boolean DEFAULT false NOT NULL,
	"tax_status_source" text,
	"tax_status_checked_at" timestamp with time zone,
	"credit_limit" numeric(14, 2),
	"payment_term_days" integer,
	"credit_hold" boolean DEFAULT false NOT NULL,
	"credit_hold_reason" text,
	"note" text,
	"status" text DEFAULT 'ACTIVE' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "customers_code_key" UNIQUE("code"),
	CONSTRAINT "customers_code_format" CHECK ("customers"."code" ~ '^[0-9]{1,20}$'),
	CONSTRAINT "customers_kind" CHECK ("customers"."kind" IN ('COMPANY', 'INDIVIDUAL')),
	CONSTRAINT "customers_name" CHECK (length("customers"."name") BETWEEN 1 AND 200),
	CONSTRAINT "customers_reg_no" CHECK ("customers"."reg_no" IS NULL OR length("customers"."reg_no") BETWEEN 1 AND 20),
	CONSTRAINT "customers_tin" CHECK ("customers"."tin" IS NULL OR "customers"."tin" ~ '^[0-9]{11,14}$'),
	CONSTRAINT "customers_tin_source" CHECK (("customers"."tin" IS NULL) = ("customers"."tin_source" IS NULL) AND ("customers"."tin_source" IS NULL OR "customers"."tin_source" IN ('LOOKUP', 'MANUAL'))),
	CONSTRAINT "customers_consumer_no" CHECK ("customers"."consumer_no" IS NULL OR ("customers"."kind" = 'INDIVIDUAL' AND "customers"."consumer_no" ~ '^[0-9]{8}$')),
	CONSTRAINT "customers_phone" CHECK ("customers"."phone" IS NULL OR "customers"."phone" ~ '^[+]976[0-9]{8}$'),
	CONSTRAINT "customers_tax_status" CHECK (("customers"."tax_status_source" IS NULL) = ("customers"."tax_status_checked_at" IS NULL)
        AND ("customers"."tax_status_source" IS NULL OR "customers"."tax_status_source" IN ('LOOKUP', 'MANUAL'))
        AND ("customers"."tax_status_source" IS NOT NULL OR NOT ("customers"."vat_payer" OR "customers"."city_payer"))),
	CONSTRAINT "customers_credit_limit" CHECK ("customers"."credit_limit" IS NULL OR "customers"."credit_limit" >= 0),
	CONSTRAINT "customers_payment_term" CHECK ("customers"."payment_term_days" IS NULL OR "customers"."payment_term_days" BETWEEN 0 AND 365),
	CONSTRAINT "customers_credit_hold_reason" CHECK ("customers"."credit_hold_reason" IS NULL OR ("customers"."credit_hold" AND length("customers"."credit_hold_reason") BETWEEN 1 AND 300)),
	CONSTRAINT "customers_note" CHECK ("customers"."note" IS NULL OR length("customers"."note") BETWEEN 1 AND 1000),
	CONSTRAINT "customers_status" CHECK ("customers"."status" IN ('ACTIVE', 'INACTIVE'))
);
